files.grip:
version: 1
quantities:
  grip:
    rule_bases:
      water:
        inputs:
          water:
            universe: [0, 100]
            terms:
              dry: {trapezoid: [0, 0, 0, 50]}
              wet: {triangle: [0, 50, 100]}
              flooded: {trapezoid: [50, 100, 100, 100]}
        rules:
          - if: (water IS dry)
            then: {low: 0.90, high: 1.10}
          - if: (water IS wet)
            then: {low: 0.65, high: 0.85}
          - if: (water IS flooded)
            then: {low: 0.45, high: 0.65}

files.operators:
version: 1
quantities:
  q:
    rule_bases:
      b:
        inputs:
          x:
            universe: [-10, 10]
            terms:
              neg: {gaussian: [-10, 6]}
              zero: {gaussian: [0, 3]}
              pos: {trapezoid: [0, 6, 10, 10]}
          y:
            universe: [0, 1]
            terms:
              lo: {triangle: [0, 0, 0.7]}
              hi: {triangle: [0.3, 1, 1]}
        rules:
          - if: (x IS neg) AND (y IS lo)
            then: {a: -1, b: 3}
          - if: (x IS zero) OR (y IS hi)
            then: {a: 0.5, b: 2}
          - if: ((y IS lo) OR (x IS pos)) AND (NOT (x IS neg))
            then: {a: 2, b: -4}
          - if: NOT ((x IS zero) AND (y IS hi))
            then: {a: 0, b: 1}
